/**
 * CCIP SDK example — generated by chainlink-ccip-skill (Cap 4 evaluation).
 *
 * Mirrors our manual deployment: transfer the BnM CCT from Ethereum Sepolia
 * to Arbitrum Sepolia, paying fees in LINK, then poll delivery status.
 *
 * Run: OPENAI unrelated; needs SEPOLIA_RPC_URL + PRIVATE_KEY env vars.
 *   npm install @chainlink/ccip-sdk
 *   npx tsx transfer-bnm-sepolia-to-arb.ts
 *
 * NOTE (eval): addresses are our real testnet deployment. Prefer a cast keystore
 * over a raw PRIVATE_KEY in real use — see eval doc feedback.
 */
import {
  EVMChain,
  networkInfo,
  CCIPAPIClient,
  withRetry,
  getCCIPExplorerUrl,
  CCIPError,
} from "@chainlink/ccip-sdk";
import { Wallet } from "ethers";

// --- Our deployment constants (Ethereum Sepolia -> Arbitrum Sepolia) ---
const SEPOLIA_RPC_URL = process.env.SEPOLIA_RPC_URL ?? "https://ethereum-sepolia-rpc.publicnode.com";
const ROUTER_SEPOLIA = "0x0BF3dE8c5D3e8A2B34D2BEeB17ABfCeBaf363A59";
const LINK_SEPOLIA = "0x779877A7B0D9E8603169DdbD7836e478b4624789";
const BNM_TOKEN_SEPOLIA = "0x6F644Dd5d6675Cee778BAe9022E4546a7aE7F0c4";
const RECEIVER = "0x4F8089d0AE682Da4Eb7227cfF049c09242c667e4"; // our EOA on Arbitrum Sepolia
const TRANSFER_AMOUNT = 10_000n; // raw units, matching our manual transfer

async function main() {
  const source = await EVMChain.fromUrl(SEPOLIA_RPC_URL);
  const destChainSelector = networkInfo("ethereum-testnet-sepolia-arbitrum-1").chainSelector;

  const message = {
    receiver: RECEIVER,
    tokenAmounts: [{ token: BNM_TOKEN_SEPOLIA, amount: TRANSFER_AMOUNT }],
    extraArgs: { gasLimit: 0n, allowOutOfOrderExecution: true },
    feeToken: LINK_SEPOLIA, // pay fees in LINK
  };

  // 1. Fee preflight — present to user before executing.
  const fee = await source.getFee({ router: ROUTER_SEPOLIA, destChainSelector, message });
  console.log(`Estimated fee: ${fee.toString()} (LINK juels)`);

  // 2. Execute the transfer (SDK handles token approval internally).
  const wallet = new Wallet(requireEnv("PRIVATE_KEY"), source.provider);
  const request = await source.sendMessage({
    router: ROUTER_SEPOLIA,
    destChainSelector,
    message: { ...message, fee },
    wallet,
  });
  console.log("Send tx:", request.tx.hash);
  console.log("Message ID:", request.message.messageId);
  console.log("Explorer:", getCCIPExplorerUrl("msg", request.message.messageId));

  // 3. Poll destination delivery status (recent messages need retry to be indexed).
  const api = new CCIPAPIClient();
  try {
    const result = await withRetry(() => api.getMessageById(request.message.messageId), {
      maxRetries: 10,
      initialDelayMs: 5000,
      maxDelayMs: 30000,
      backoffMultiplier: 1.5,
      respectRetryAfterHint: true,
    });
    console.log("Status:", result.metadata.status);
    console.log("Dest tx:", result.metadata.receiptTransactionHash ?? "(pending)");
  } catch (error) {
    if (CCIPError.isCCIPError(error)) {
      console.error(`CCIP error: ${error.message}${error.isTransient ? " (transient)" : ""}`);
    } else {
      throw error;
    }
  }
}

function requireEnv(name: string): string {
  const v = process.env[name];
  if (!v) throw new Error(`Missing required env var: ${name}`);
  return v;
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});
